style.css:
/* Liquid Glass Copilot - copilot.microsoft.com */

/* Đổi các màu này để chỉnh phong cách */
:root {
  --my-bg1: #141a3a;
  --my-bg2: #3b1d52;
  --my-bg3: #0e4150;
  --my-accent: #8ab4ff;
  --my-text: #f2f5ff;
  --my-glass-bg: rgba(255, 255, 255, 0.10);
  --my-glass-border: rgba(255, 255, 255, 0.28);
  --my-blur: 22px;
  --my-radius: 20px;
}

/* nền gradient cố định phía sau */
html, body {
  background: linear-gradient(135deg, var(--my-bg1), var(--my-bg2) 55%, var(--my-bg3)) fixed !important;
  color: var(--my-text) !important;
  font-family: -apple-system, "SF Pro Display", "Segoe UI Variable", "Segoe UI", Inter, sans-serif !important;
}

/* hiệu ứng kính: ô nhập, popup, menu */
textarea,
input[type="text"],
input[type="search"],
[role="dialog"],
[role="menu"],
[role="listbox"] {
  background: var(--my-glass-bg) !important;
  -webkit-backdrop-filter: blur(var(--my-blur)) saturate(180%) !important;
  backdrop-filter: blur(var(--my-blur)) saturate(180%) !important;
  border: 1px solid var(--my-glass-border) !important;
  border-radius: var(--my-radius) !important;
  color: var(--my-text) !important;
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.35),
    0 8px 32px rgba(0, 0, 0, 0.25) !important;
}

/* nút bấm dạng viên kính */
button {
  background: var(--my-glass-bg) !important;
  -webkit-backdrop-filter: blur(14px) saturate(160%) !important;
  backdrop-filter: blur(14px) saturate(160%) !important;
  border: 1px solid var(--my-glass-border) !important;
  border-radius: 999px !important;
  color: var(--my-text) !important;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.3) !important;
  transition: background 0.2s ease, transform 0.2s ease !important;
}
button:hover {
  background: rgba(255, 255, 255, 0.2) !important;
  transform: translateY(-1px);
}

/* link và màu chọn chữ */
a { color: var(--my-accent) !important; }
::selection { background: var(--my-accent); color: #0b1020; }

/* thanh cuộn mảnh, trong suốt */
* { scrollbar-width: thin; scrollbar-color: rgba(255,255,255,0.35) transparent; }

/* ảnh bo góc mềm */
img { border-radius: 14px; }
